-- Reconstruct lookup tables absent from legacy migrations, from the checked-in CSV.
CREATE TABLE public.geo_provinces(id integer PRIMARY KEY,name_en text NOT NULL,headquarter text,website text);
CREATE TABLE public.geo_districts(id integer PRIMARY KEY,province_id integer REFERENCES public.geo_provinces(id),name_en text NOT NULL,headquarter text,website text);
CREATE TABLE public.geo_local_levels(id integer PRIMARY KEY,district_id integer REFERENCES public.geo_districts(id),name_en text NOT NULL,category_id integer,category_label text,area_sq_km numeric,website text,num_wards integer);
ALTER TABLE public.geo_provinces ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public geography read" ON public.geo_provinces FOR SELECT USING (true);
ALTER TABLE public.geo_districts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public geography read" ON public.geo_districts FOR SELECT USING (true);
ALTER TABLE public.geo_local_levels ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public geography read" ON public.geo_local_levels FOR SELECT USING (true);
